import pandas as pd
import numpy as np

def run_data_pipeline(raw_df, required_columns, max_missing_fraction=0.1):
    errors = []

    missing_columns = set(required_columns) - set(raw_df.columns)
    if missing_columns:
        errors.append(f"Missing expected columns: {missing_columns}")

    for column in required_columns:
        if column in raw_df.columns:
            missing_fraction = raw_df[column].isna().mean()
            if missing_fraction > max_missing_fraction:
                errors.append(f"Column '{column}' has {missing_fraction:.1%} missing, exceeds {max_missing_fraction:.0%} threshold")

    duplicate_count = raw_df.duplicated().sum()
    if duplicate_count > 0:
        raw_df = raw_df.drop_duplicates()
        print(f"Removed {duplicate_count} duplicate rows")

    if errors:
        print("Data pipeline validation FAILED:")
        for error in errors:
            print(f"  - {error}")
        return None

    print(f"Data pipeline validation passed: {len(raw_df)} clean rows ready for the ML Pipeline")
    return raw_df

rng = np.random.RandomState(42)
raw_df = pd.DataFrame({
    "user_id": range(1000),
    "feature_a": rng.normal(size=1000),
    "feature_b": rng.normal(size=1000),
})
raw_df = pd.concat([raw_df, raw_df.iloc[:20]], ignore_index=True)  # simulate 20 duplicate rows

clean_df = run_data_pipeline(raw_df, required_columns=["user_id", "feature_a", "feature_b"])
